// Read-only attribution of the stale host-admission/host-policy bundles: scripts/build-host-admission.mjs's exact esbuild
// options, write:false, cwd = main. Variant 'current' swaps nothing (control: plugin is neutral); 'prior' substitutes ONLY
// network/platform-host-policy-config.mjs with its previous reviewed bytes (402c73b8...). Compares with main's stored bundles.
import { createRequire } from "node:module"; import fs from "node:fs"; import path from "node:path"; import crypto from "node:crypto";
const M = process.cwd(); const { build } = createRequire(path.join(M, "package.json"))("esbuild");
const SWAP = path.join(M, "network/platform-host-policy-config.mjs"), prior = fs.readFileSync(process.argv[2], "utf8");
const sha = (b) => crypto.createHash("sha256").update(b).digest("hex");
for (const variant of ["plain", "current", "prior"]) for (const [entry, file] of [["network/host-admission-runtime.mjs", "windows/node/host-admission.bundle.mjs"], ["network/metal-host-policy.mjs", "metal/guest/host-policy.bundle.mjs"]]) {
  const plugins = variant === "plain" ? [] : [{ name: "swap", setup(b) { b.onLoad({ filter: /platform-host-policy-config\.mjs$/ }, (a) => {
    if (a.path !== SWAP) throw Error("unexpected " + a.path);
    return { contents: variant === "prior" ? prior : fs.readFileSync(SWAP, "utf8"), loader: "js" }; }); } }];
  const r = await build({ entryPoints: [entry], outfile: file, write: false, bundle: true, platform: "node", format: "esm", target: "node20", minify: true,
    banner: { js: "// Generated by scripts/build-host-admission.mjs; edit " + entry + "." }, plugins, metafile: true });
  const out = Buffer.from(r.outputFiles[0].contents), stored = fs.readFileSync(file);
  const inputs = Object.keys(r.metafile.inputs).filter((i) => !i.includes("node_modules"));
  console.log(variant.padEnd(7), file, "built", sha(out).slice(0, 16), "stored", sha(stored).slice(0, 16), out.equals(stored) ? "EQUALS-STORED" : "DIFFERS", "localInputs", inputs.length, "includesConfig", inputs.includes("network/platform-host-policy-config.mjs"));
}
